arguments.code:
ClearAll["Global\`*"];
kap=sig*cc/(me*cc^2);
qhot=-4*kap*nb*xx*kb*temp*ucoef*er;
qplanck=4*kap*nb*xx*kb*ur*(tr-temp);
quv=kap*nb*xx*(mv-4*kb*temp*uv);
gh=FullSimplify[2*(qhot+quv)/(3*kb*temp*nb*hh*eta)];
gp=FullSimplify[2*(qplanck+quv)/(3*kb*temp*nb*hh*eta)];
bh=-8*kap*ucoef*er/3+(2*kap/3)*(mv/(kb*temp)-4*uv);
bp=(8*kap/3)*ur*(tr/temp-1)+(2*kap/3)*(mv/(kb*temp)-4*uv);
aHot=(8*kap/3)*(xx/eta)*(ucoef*er+uv);
bHot=(2*kap/3)*(xx/eta)*mv/kb;
aPlanck=(8*kap/3)*(xx/eta)*(ur+uv);
bPlanck=(8*kap/3)*(xx/eta)*(ur*tr+mv/(4*kb));
thermalSolution=tinit*Exp[-aa*tt]+(bb/aa)*(1-Exp[-aa*tt]);
assumptions={sig>0,cc>0,me>0,kb>0,nb>0,eta>0,hh>0,temp>0,xx>=0,ucoef>=0,er>=0,ur>=0,tr>=0,uv>=0,mv>=0};
records=<|
"source_to_reduced_actual_hot"->FullSimplify[gh-xx*bh/(hh*eta)],
"source_to_reduced_planck"->FullSimplify[gp-xx*bp/(hh*eta)],
"hot_temperature_only_derivative"->FullSimplify[temp*D[2*qhot/(3*kb*temp*nb*hh*eta),temp]],
"actual_plus_uv_logT_derivative"->FullSimplify[temp*D[gh,temp]+2*kap*xx*mv/(3*hh*eta*kb*temp)],
"planck_plus_uv_logT_derivative"->FullSimplify[temp*D[gp,temp]+(xx/(hh*eta))*(8*kap*ur*tr/(3*temp)+2*kap*mv/(3*kb*temp))],
"actual_abundance_scaled_derivative"->FullSimplify[sj*(D[gh/.{xx->xx+qj*eps,eta->eta+wj*eps},eps]/.eps->0)-sj*bh*(qj*eta-xx*wj)/(hh*eta^2)],
"planck_abundance_scaled_derivative"->FullSimplify[sj*(D[gp/.{xx->xx+qj*eps,eta->eta+wj*eps},eps]/.eps->0)-sj*bp*(qj*eta-xx*wj)/(hh*eta^2)],
"actual_geometry_direction_derivative"->FullSimplify[(D[gh/.{hh->hh*Exp[hgrad*eps],er->er+egrad*eps},eps]/.eps->0)-(-gh*hgrad-8*kap*ucoef*xx*egrad/(3*hh*eta))],
"planck_geometry_direction_derivative"->FullSimplify[(D[gp/.hh->hh*Exp[hgrad*eps],eps]/.eps->0)+gp*hgrad],
"tau_column_zero"->FullSimplify[D[gh,tau]+D[gp,tau]],
"neutral_abundance_derivative_limit"->FullSimplify[Limit[bh*(qj*eta-xx*wj)/(hh*eta^2),xx->0]-bh*qj/(hh*eta)],
"actual_affine_temperature_identity"->FullSimplify[hh*temp*gh-(-aHot*temp+bHot)],
"planck_affine_temperature_identity"->FullSimplify[hh*temp*gp-(-aPlanck*temp+bPlanck)],
"frozen_temperature_ode_residual"->FullSimplify[D[thermalSolution,tt]+aa*thermalSolution-bb],
"frozen_temperature_initial_residual"->FullSimplify[(thermalSolution/.tt->0)-tinit],
"zero_A_limit_residual"->FullSimplify[Limit[thermalSolution,aa->0]-(tinit+bb*tt)],
"relaxation_weight_bounds"->FullSimplify[0<=Exp[-aa*tt]<=1,Assumptions->{aa>=0,tt>=0}],
"actual_physical_coefficients_nonnegative"->FullSimplify[aHot>=0&&bHot>=0,Assumptions->assumptions],
"planck_physical_coefficients_nonnegative"->FullSimplify[aPlanck>=0&&bPlanck>=0,Assumptions->assumptions],
"gas_bath_local_ledger"->FullSimplify[(qabs-qescape+qc+quvLedger)-qc-qabs-quvLedger+qescape],
"variable_particle_caloric_identity"->FullSimplify[nb*((3*kb/2)*(eta*(-2*hh*temp+2*qkin/(3*kb*nb*eta)-temp*etadot/eta)+temp*etadot)+ionrate+3*hh*kb*temp*eta)-(qkin+nb*ionrate)],
"hydrogen_to_baryon_heat_capacity_ratio"->FullSimplify[(xx/eta/.{xx->xeH*nH/nb,eta->(1+fHe+xeH)*nH/nb})-xeH/(1+fHe+xeH)],
"FLRW_Planck_temperature_coefficient"->FullSimplify[(hh*temp*(gp/.{uv->0,mv->0,ur->arad*tr^4}))-(8*sig*arad*tr^4/(3*me*cc))*(xx/eta)*(tr-temp)],
"redshift_sign_and_adiabatic_conversion"->FullSimplify[(-2*hh*temp+gamma*(tr-temp))/(-hh*(1+zz))-(2*temp/(1+zz)+gamma*(temp-tr)/(hh*(1+zz)))],
"Planck_equilibrium_zero"->FullSimplify[qplanck/.temp->tr],
"branch_difference_identity"->FullSimplify[(qplanck-qhot)-(-4*kap*nb*xx*kb*temp*(ur-ucoef*er)+4*kap*nb*xx*kb*ur*tr)]
|>;
ExportString[<|"residuals_and_predicates"->records,"all_checks_pass"->And@@(TrueQ[#===0||#===True]&/@Values[records]),"reduced_g_actual"->ToString[gh,InputForm],"reduced_g_planck"->ToString[gp,InputForm],"frozen_solution"->ToString[thermalSolution,InputForm],"assumptions"->ToString[assumptions,InputForm]|>,"RawJSON"]
